&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;o&quot; data-font=&quot;Courier New&quot; data-listid=&quot;24&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Courier New&amp;quot;,&amp;quot;469769242&amp;quot;:[9675],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;o&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;2&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;GPU-accelerated computing&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What can you expect from us&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A comprehensive benefits package that includes&amp;nbsp;an annual bonus plan,&amp;nbsp;private medical insurance, life insurance, and a&amp;nbsp;contributory pension scheme&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Equity, so that our team can share in the long-term success of Riverlane&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;28 days annual leave,&amp;nbsp;plus bank holidays and enhanced family leave&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A diverse work environment that brings together experts in many fields (including software and hardware development, quantum information theory,&amp;nbsp;physics&amp;nbsp;and maths) and over 20 different nationalities&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A learning environment that encourages individual, team and company growth and&amp;nbsp;development, including a regular programme of learning events and training and conference budgets&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;How to apply&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Please upload a CV and covering letter by clicking &#39;Apply&#39;. Your covering letter should explain why you are applying for the job and what skills and experience you can bring to the role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We review CVs as we receive them and interview as soon as we have applications that&amp;nbsp;look&amp;nbsp;like a good match. We do not use closing dates. So, please&amp;nbsp;apply as soon as possible to avoid&amp;nbsp;missing out on&amp;nbsp;this role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you have any queries, please contact&amp;nbsp;&lt;/span&gt;&lt;a ----- data-contrast=&quot;none&quot;&gt;&lt;span ----- data-ccp-charstyle=&quot;Hyperlink&quot;&gt;com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Everyone is welcome at Riverlane. We are an equal opportunities employer and encourage applications from eligible and suitably qualified candidates regardless of age, disability, ethnicity, gender, gender reassignment, religion or belief, sexual orientation, marital or civil partnership status, or pregnancy and maternity/paternity.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Women and other underrepresented groups may be less likely to apply for a role unless they meet all or&amp;nbsp;nearly all&amp;nbsp;of the requirements.&amp;nbsp;&amp;nbsp;If this applies to you, we still encourage you to apply - you may be a great fit, even if you&amp;nbsp;don’t&amp;nbsp;meet every single qualification.&amp;nbsp;We’d&amp;nbsp;love to hear from you.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you need any adjustments made to the application or selection process so you can do your best, please let us know. We will be happy to help.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;GDPR notice: Riverlane collects and processes personal data in accordance with applicable data protection laws. If you are a European Job Applicant see the&amp;nbsp;&lt;strong&gt;&lt;a id=&quot;OWA843b0309-1485-8922-978c-b4a29d28b8a6&quot; class=&quot;x_x_fui-Link x_x____1q1shib x_x_f2hkw1w x_x_f3rmtva x_x_f1ewtqcl x_x_fyind8e x_x_f1k6fduh x_x_f1w7gpdv x_x_fk6fouc x_x_fjoy568 x_x_figsok6 x_x_f1s184ao x_x_f1mk8lai x_x_fnbmjn9 x_x_f1o700av x_x_f13mvf36 x_x_f1cmlufx x_x_f9n3di6 x_x_f1ids18y x_x_f1tx3yz7 x_x_f1deo86v x_x_f1eh06m1 x_x_f1iescvh x_x_fhgqx19 x_x_f1olyrje x_x_f1p93eir x_x_f1nev41a x_x_f1h8hb77 x_x_f1lqvz6u x_x_f10aw75t x_x_fsle3fq x_x_f17ae5zn x_x_OWAAutoLink&quot; href=&quot;https://riverlane.workable.com/gdpr_policy/v1?lang=en&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;privacy notice&lt;/a&gt;&lt;/strong&gt;&amp;nbsp;for further details.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;Find Jobs in United Kingdom on Arbeitnow

&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;Cambridge, UK | Full-time | Fixed-term, 10–12 weeks | Hybrid&lt;/p&gt;
&lt;p&gt;Salary: £30,000–£35,000 per annum, depending on experience, paid pro rata for the internship duration.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About us&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Riverlane’s&amp;nbsp;mission is to master quantum error correction (QEC) and unlock a new age of human progress. From advances in material and climate science, to complex chemistry simulation for new drug design, quantum computers will help humanity solve some of its most important challenges. But without QEC, the industry’s defining technical challenge, such breakthroughs can never be achieved.&amp;nbsp;&amp;nbsp;Riverlane is the world leader in QEC technology. QEC is a complex problem that requires a range of skills,&amp;nbsp;talent&amp;nbsp;and passion.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW243923852 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;Having raised more than $125M in funding to date to accelerate our&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;cutting-edge&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;&amp;nbsp;R&amp;amp;D in quantum error correction (QEC), Riverlane partners with many of the world’s leading quantum hardware providers and government agencies to make fault-tolerant quantum computing a reality.&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;We’re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;&amp;nbsp;making remarkable progress and growing fast. &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW243923852 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the role&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our full-time summer internships give current students in technical fields the opportunity to apply their skills and expertise in an industrial setting.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will join us at our head office in Cambridge, UK, for 10 to 12 weeks, working alongside talented software and hardware engineers, mathematicians, quantum information theorists and physicists who are experts in their fields.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will have a dedicated supervisor and work on a project designed to make the best use of your existing skills while developing your knowledge of quantum computing and quantum error correction. We will support you in producing a meaningful piece of work that you can be proud of by the end of your internship.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Previous interns have committed code to industry-standard open-source compilers, co-authored research papers and led the design of new software tools.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What you will do&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;
&lt;p data-pm-slice=&quot;1 1 [&amp;quot;list&amp;quot;,{&amp;quot;spread&amp;quot;:false,&amp;quot;start&amp;quot;:0,&amp;quot;end&amp;quot;:104},&amp;quot;regular_list_item&amp;quot;,{&amp;quot;start&amp;quot;:0,&amp;quot;end&amp;quot;:104}]&quot;&gt;Design, develop and test software that contributes to Riverlane’s quantum error correction technology.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Work closely with colleagues across software engineering, research and other technical disciplines&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Explore ideas, evaluate different approaches and contribute to technical problem-solving&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Communicate your work clearly through discussions, presentations and written reports&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop your understanding of quantum computers, quantum error correction and their potential applications&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-pm-slice=&quot;1 3 []&quot;&gt;&lt;strong&gt;What we need&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-spread=&quot;false&quot;&gt;
&lt;li&gt;
&lt;p&gt;You must be a current student at the time of application, studying towards a Bachelor’s degree (second year or later), Master’s degree or PhD.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;You must be studying Computer Science, Software Engineering, Physics, Chemistry, Mathematics, Electronic Engineering or another related technical subject.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience using at least one general-purpose programming language, demonstrated through coursework, personal projects or research.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;An understanding of core programming concepts, including data structures and algorithms.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Strong analytical and problem-solving skills.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Clear written and verbal communication skills.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;The ability to take initiative and work effectively as part of a team.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;An interest in applying your software skills to quantum computing; prior quantum computing knowledge or experience is not required.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Availability to work full-time for 10–12 weeks.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Even better if…&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-spread=&quot;false&quot;&gt;
&lt;li&gt;
&lt;p&gt;You have experience with C++ or Python, the main languages you will use during the internship.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;You have experience writing tests, debugging code or using version control tools such as Git.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;You have developed software as part of a collaborative project.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Important notes&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;
&lt;p data-pm-slice=&quot;1 1 [&amp;quot;list&amp;quot;,{&amp;quot;spread&amp;quot;:false,&amp;quot;start&amp;quot;:0,&amp;quot;end&amp;quot;:206},&amp;quot;regular_list_item&amp;quot;,{&amp;quot;start&amp;quot;:0,&amp;quot;end&amp;quot;:206}]&quot;&gt;You must already have the right to work in the UK for the full duration of the internship. If you hold a UK student visa, please check that its conditions allow you to undertake this full-time internship.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;PhD students may need to temporarily step away from their PhD to complete the internship. This may affect their right-to-work status, and applicants should check their individual circumstances&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You must be available to work full-time for 10 to 12 weeks during the summer vacation period&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will be required to sign an agreement assigning ownership of any intellectual property produced during your internship to Riverlane&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Internships are based at our head office in Cambridge, UK&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;&lt;strong&gt;How to apply&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Please upload a CV and covering letter through our careers page. Your CV should include the grades you have received so far in your degree(s). Your covering letter should explain why you are applying for the software engineering internship and what skills and experience you would bring.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Deadline&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Please submit your application by &lt;strong&gt;Friday 6 November 2026&lt;/strong&gt;. Interviews will be held in Cambridge, or virtually if required.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What can you expect from us&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Alongside a competitive salary, we offer private medical insurance, a health cash plan and life assurance, as well many other benefits.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You can also expect a diverse work environment that brings together experts in many fields (including software and hardware development, quantum information theory, physics and maths) and over 25 different nationalities.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you have any queries, please contact&amp;nbsp;&lt;/span&gt;&lt;a ----- data-contrast=&quot;none&quot;&gt;&lt;span ----- data-ccp-charstyle=&quot;Hyperlink&quot;&gt;com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt; Please do not send your applications to this email address, all applications should be submitted via our careers page.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Everyone is welcome at Riverlane. We are an equal opportunities employer and encourage applications from eligible and suitably qualified candidates regardless of age, disability, ethnicity, gender, gender reassignment, religion or belief, sexual orientation, marital or civil partnership status, or pregnancy and maternity/paternity.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Women and other underrepresented groups may be less likely to apply for a role unless they meet all or&amp;nbsp;nearly all&amp;nbsp;of the requirements.&amp;nbsp;&amp;nbsp;If this applies to you, we still encourage you to apply - you may be a great fit, even if you&amp;nbsp;don’t&amp;nbsp;meet every single qualification.&amp;nbsp;We’d&amp;nbsp;love to hear from you.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you need any adjustments made to the application or selection process so you can do your best, please let us know. We will be happy to help.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;GDPR notice: Riverlane collects and processes personal data in accordance with applicable data protection laws. If you are a European Job Applicant see the&amp;nbsp;&lt;strong&gt;&lt;a id=&quot;OWA843b0309-1485-8922-978c-b4a29d28b8a6&quot; class=&quot;x_x_fui-Link x_x____1q1shib x_x_f2hkw1w x_x_f3rmtva x_x_f1ewtqcl x_x_fyind8e x_x_f1k6fduh x_x_f1w7gpdv x_x_fk6fouc x_x_fjoy568 x_x_figsok6 x_x_f1s184ao x_x_f1mk8lai x_x_fnbmjn9 x_x_f1o700av x_x_f13mvf36 x_x_f1cmlufx x_x_f9n3di6 x_x_f1ids18y x_x_f1tx3yz7 x_x_f1deo86v x_x_f1eh06m1 x_x_f1iescvh x_x_fhgqx19 x_x_f1olyrje x_x_f1p93eir x_x_f1nev41a x_x_f1h8hb77 x_x_f1lqvz6u x_x_f10aw75t x_x_fsle3fq x_x_f17ae5zn x_x_OWAAutoLink&quot; href=&quot;https://riverlane.workable.com/gdpr_policy/v1?lang=en&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;privacy notice&lt;/a&gt;&lt;/strong&gt;&amp;nbsp;for further details.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;Find Jobs in United Kingdom on Arbeitnow

&lt;p&gt;Cambridge, UK | Full-time | Permanent&lt;/p&gt;
&lt;p&gt;Salary: £81,000 - £95,000 DOE&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About us&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Riverlane’s mission is to master quantum error correction (QEC) and unlock a new age of human progress. From advances in material and climate science, to complex chemistry simulation for new drug design, quantum computers will help humanity solve some of its most important challenges. But without QEC, the industry’s defining technical challenge, such breakthroughs can never be achieved.&amp;nbsp; Riverlane is the world leader in QEC technology. QEC is a complex problem that requires a range of skills, talent and passion.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Having raised more than $125M in funding to date to accelerate our cutting-edge R&amp;amp;D in quantum error correction (QEC), Riverlane partners with many of the world’s leading quantum hardware providers and government agencies to make fault-tolerant quantum computing a reality. We are making remarkable progress and growing fast.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Riverlane, our mission is to make it possible for anyone to write and run fault-tolerant programs on a quantum computer. A key part of that mission is &lt;a href=&quot;https://github.com/Deltakit/deltakit&quot;&gt;Deltakit&lt;/a&gt;, our open-source, user-facing platform for building, simulating and interpreting QEC experiments. As a Senior Software Engineer, you will own and lead the development of &lt;a href=&quot;https://github.com/Deltakit/deltakit&quot;&gt;Deltakit&lt;/a&gt;, shaping its direction and ensuring it evolves to meet the needs of a growing and highly technical user community.&lt;/p&gt;
&lt;p&gt;This role sits at the intersection of research and engineering. You will take cutting-edge ideas from the forefront of QEC and turn them into robust, intuitive software that researchers can rely on. Day to day, this means driving the design and delivery of new features, improving performance and usability, and ensuring the platform scales as adoption grows. You’ll play a key role in planning and prioritising the development roadmap, aligning technical delivery with research milestones, user needs, and broader organisational goals, as well as defining technical direction, making architectural decisions, and setting the standard for high-quality, well-engineered code.&lt;/p&gt;
&lt;p&gt;You will also be closely connected to the people who use what we build. By engaging with researchers, engineers and the wider QEC community, you’ll help support adoption of &lt;a href=&quot;https://github.com/Deltakit/deltakit&quot;&gt;Deltakit&lt;/a&gt;, understand how it’s being used in practice, and translate real-world feedback into meaningful improvements. You’ll also play a key role in planning and prioritising the development roadmap, aligning technical delivery with research milestones, user needs, and broader organisational goals. Through this, you’ll ensure the software not only reflects the latest research, but is accessible, reliable and impactful.&lt;/p&gt;
&lt;p&gt;Riverlane operates at the forefront of a fast-moving and evolving field. You’ll work as part of a collaborative, multidisciplinary team where ideas are shared openly and learning is continuous. As priorities shift and the technology develops, you’ll help guide the platform forward through both technical leadership and thoughtful planning, bringing clarity, direction and momentum to complex challenges, and playing a central role in advancing Riverlane’s leadership in QEC software.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you will do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead significant parts of both the internal and external software stack for error-corrected quantum computing systems&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Turn internal tools into external and public ones. Own the complete software cycle process: design, development, testing, builds, workflows, releases&lt;/li&gt;
&lt;li&gt;Mentor, guide and lead engineers in the team&lt;/li&gt;
&lt;li&gt;Lead collaboration with other engineering teams to integrate their software and hardware artifacts with &lt;a href=&quot;https://github.com/Deltakit/deltakit&quot;&gt;Deltakit&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Engage with the community of users and researchers to identify needs and formulate adequate response&lt;/li&gt;
&lt;li&gt;Contribute actively to open-source projects and lead the&amp;nbsp;&lt;a href=&quot;https://github.com/Deltakit/deltakit&quot;&gt;Deltakit&lt;/a&gt; open-source community&lt;/li&gt;
&lt;li&gt;Organise and run workshops and tutorials for the community of users&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What we need&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are considering a range of experience and are therefore advertising this role at different levels of seniority.&amp;nbsp; Please apply to the role you feel best suits your skills and experience.&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong technical foundation (e.g. computer science, mathematics, physics or similar)&lt;/li&gt;
&lt;li&gt;Experience designing and building high-quality scientific or technical software, primarily in Python&lt;/li&gt;
&lt;li&gt;Ability to translate complex, research-driven concepts into robust, scalable and user-friendly solutions&lt;/li&gt;
&lt;li&gt;Broad understanding of software systems (e.g. compilers, operating systems, computer architecture)&lt;/li&gt;
&lt;li&gt;Experience shipping software to users and maintaining high engineering standards&lt;/li&gt;
&lt;li&gt;Curiosity and a strong drive to learn and solve complex problems&lt;/li&gt;
&lt;li&gt;Collaborative mindset, with experience working across diverse teams&lt;/li&gt;
&lt;li&gt;Strong written and verbal communication skills&lt;/li&gt;
&lt;li&gt;Ability to shape technical direction, drive best practices, and support others through mentorship and leadership&lt;/li&gt;
&lt;li&gt;Interest in contributing to the quantum open-source ecosystem&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Even better if you have&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience with a strongly typed language (e.g. C++ or Rust)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you can expect from us&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A comprehensive benefits package that includes an annual bonus plan, private medical insurance, life insurance, and a contributory pension scheme&lt;/li&gt;
&lt;li&gt;Equity, so that our team can share in the long-term success of Riverlane&lt;/li&gt;
&lt;li&gt;28 days annual leave, plus bank holidays and enhanced family leave&lt;/li&gt;
&lt;li&gt;A diverse work environment that brings together experts in many fields (including software and hardware development, quantum information theory, physics and maths) and over 20 different nationalities&lt;/li&gt;
&lt;li&gt;A learning environment that encourages individual, team and company growth and development, including a regular programme of learning events and training and conference budgets&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How to apply&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Please upload a CV and covering letter by clicking &#39;Apply Now&#39;. Your covering letter should explain why you are applying for the job and what skills and experience you can bring to the role.&lt;/p&gt;
&lt;p&gt;We review CVs as we receive them and interview as soon as we have applications that look like a good match. We do not use closing dates. So, please apply as soon as possible to avoid missing out on this role.&lt;/p&gt;
&lt;p&gt;If you have any queries, please contact &lt;a ----------
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;#LI-KW1&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Everyone is welcome at Riverlane. We are an equal opportunities employer and encourage applications from eligible and suitably qualified candidates regardless of age, disability, ethnicity, gender, gender reassignment, religion or belief, sexual orientation, marital or civil partnership status, or pregnancy and maternity/paternity.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Women and other underrepresented groups may be less likely to apply for a role unless they meet all or nearly all the requirements.&amp;nbsp; If this applies to you, we still encourage you to apply - you may be a great fit, even if you don’t meet every single qualification. We’d love to hear from you.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;If you need any adjustments made to the application or selection process so you can do your best, please let us know. We will be happy to help.&lt;/em&gt;&lt;/p&gt;Find Jobs in United Kingdom on Arbeitnow

&lt;p&gt;Cambridge, UK, | Full-time | Permanent | Hybrid&lt;/p&gt;
&lt;p&gt;Salary: £61,500 to £80,000 DOE&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About us&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Riverlane’s&amp;nbsp;mission is to master quantum error correction (QEC) and unlock a new age of human progress. From advances in material and climate science, to complex chemistry simulation for new drug design, quantum computers will help humanity solve some of its most important challenges. But without QEC, the industry’s defining technical challenge, such breakthroughs can never be achieved.&amp;nbsp;Riverlane is the world leader in QEC technology.&amp;nbsp; It’s a complex problem that requires a range of skills,&amp;nbsp;talent&amp;nbsp;and passion.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Having raised more than $125M in funding to date to accelerate our&amp;nbsp;cutting-edge&amp;nbsp;R&amp;amp;D in quantum error correction (QEC), Riverlane partners with many of the world’s leading quantum hardware providers and governments to make fault-tolerant quantum computing a reality.&amp;nbsp;We’re&amp;nbsp;making remarkable progress and growing fast&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are looking for an exceptional Product Marketing Manager with experience in open-source software growth and adoption to lead product marketing for &lt;a href=&quot;https://www.riverlane.com/deltakit&quot;&gt;Deltakit&lt;/a&gt;, our open-source SDK for learning and adopting QEC.&lt;/p&gt;
&lt;p&gt;Deltakit is just over a year old. It has had a strong start with a steadily growing developer community and growing end-user adoption. But it’s still early days. Your mission is to make Deltakit the platform the world experiments with and adopts for quantum error correction.&lt;/p&gt;
&lt;p&gt;Education is central to Riverlane&#39;s growth strategy. You will build and scale our QEC education programme through workshops, digital learning, technical content and our interactive QEC Textbook, helping create the next generation of Deltakit developers.&lt;/p&gt;
&lt;p&gt;This role involves travelling to industry events globally, approximately 2-3 times a year.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you will do&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Develop Deltakit&#39;s positioning, messaging and value proposition, working closely with our Product and Engineering teams&lt;/li&gt;
&lt;li&gt;Segment the Deltakit value proposition and go to market strategy for different audiences: software developers, quantum computing companies and labs, and learners&lt;/li&gt;
&lt;li&gt;Increase Deltakit adoption by software developers, working closely with the Deltakit software team and community engineers. This will include in person and virtual workshop&lt;/li&gt;
&lt;li&gt;Increase Deltakit adoption by Riverlane’s QEC hardware customers at quantum computing companies, HPC centres and national labs. This will also include in person and virtual workshops&lt;/li&gt;
&lt;li&gt;Create compelling technical content, demonstrations, tutorials, case studies and adoption campaigns&lt;/li&gt;
&lt;li&gt;Partner with Engineering to improve the developer onboarding journey, documentation, tutorials and sample applications that make Deltakit easy to learn and adopt&lt;/li&gt;
&lt;li&gt;Define and monitor adoption metrics including developer engagement, community growth, product usage and conversion to Deltaflow opportunities&lt;/li&gt;
&lt;li&gt;Track SDK competitor activity and effectiveness. Report on relative adoption growth of Deltakit versus this peer group&lt;/li&gt;
&lt;li&gt;Stay abreast of important engineering, science and product developments in the industry, particularly where it relates to QEC software&lt;/li&gt;
&lt;li&gt;Represent the voice of developers and users within Riverlane, ensuring customer insight shapes product direction, messaging and the developer experience&lt;/li&gt;
&lt;li&gt;Be a key member of a collaborative Marketing team of 6-8 people&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What we need&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience in product marketing for developer tools, SDKs or open-source software&lt;/li&gt;
&lt;li&gt;Experience working in a B2B deep tech environment&lt;/li&gt;
&lt;li&gt;Proven success growing adoption of developer platforms, open-source software or technical communities&lt;/li&gt;
&lt;li&gt;Skill in articulating ‘deep tech’ in clear and compelling storytelling&lt;/li&gt;
&lt;li&gt;Experience coordinating and delivering educational events and workshops for developers and end users is highly desirable&lt;/li&gt;
&lt;li&gt;Experience working with technical audiences such as software engineers, researchers or scientific computing communities&lt;/li&gt;
&lt;li&gt;A collaborative, cross-functional team player, in line with our company values&lt;/li&gt;
&lt;li&gt;Someone who thrives in a fast-moving, rapidly evolving, self-empowering culture&lt;/li&gt;
&lt;li&gt;Excellent written and spoken English&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Even better if...&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You have product marketing experience in quantum computing, semiconductors, HPC, AI infrastructure, or another deep tech field&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What can you expect from us&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A comprehensive benefits package that includes&amp;nbsp;an annual bonus plan,&amp;nbsp;private medical insurance, life insurance, and a&amp;nbsp;contributory pension scheme&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Equity, so that our team can share in the long-term success of Riverlane&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;28 days annual leave,&amp;nbsp;plus bank holidays and enhanced family leave&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;A diverse work environment that brings together experts in many fields (including software and hardware development, quantum information theory,&amp;nbsp;physics&amp;nbsp;and maths) and over 20 different nationalities&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;A learning environment that encourages individual, team and company growth and&amp;nbsp;development, including a regular programme of learning events and training and conference budgets&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
