&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2185&quot; data-local-id=&quot;72bbff00-8681-4746-9ca4-4ae1ea03cfa3&quot;&gt;Ready for occasional business trips&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;2224&quot; data-local-id=&quot;420f9a0c-ab5b-4728-8f12-bdd34bbc7193&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;It will be&amp;nbsp;an added bonus&amp;nbsp;if you have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;07aa2efd-19d7-4376-85e2-314ed349ae63&quot; data-indent-level=&quot;1&quot;&gt;
