&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3 class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;66gea-0-0&quot;&gt;&lt;strong&gt;&lt;span data-offset-key=&quot;66gea-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;How to apply&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;div class=&quot;&quot; data-block=&quot;true&quot; data-editor=&quot;5vjqq&quot; data-offset-key=&quot;dk8ll-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;dk8ll-0-0&quot;&gt;&lt;span data-offset-key=&quot;dk8ll-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;If this opportunity interests you, please send your CV &lt;strong&gt;and a cover letter &lt;/strong&gt;outlining your relevant experience, interests and what excites you about the role.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;&quot; data-block=&quot;true&quot; data-editor=&quot;5vjqq&quot; data-offset-key=&quot;fummn-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;fummn-0-0&quot;&gt;&lt;span data-offset-key=&quot;fummn-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;We welcome applications from people with diverse backgrounds, experiences and perspectives. You don&#39;t need to meet every requirement to be a strong candidate. If the role sparks your curiosity and you&#39;d enjoy exploring how science and technology can make a difference, we&#39;d love to hear from you.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;hr&gt;
